   101→// VerifyCellKZGProofBatchFromBlobData verifies cell KZG proofs in batch format directly from blob data.
   102→// This is more efficient than reconstructing data column sidecars when you have the raw blob data and cell proofs.
   103→// For PeerDAS/Fulu, the execution client provides cell proofs in flattened format via BlobsBundleV2.
   104→// For single blob verification, it optimizes by computing cells once and verifying efficiently.
   105→func VerifyCellKZGProofBatchFromBlobData(blobs [][]byte, commitments [][]byte, cellProofs [][]byte, numberOfColumns uint64) error {
   106→	blobCount := uint64(len(blobs))
   107→	expectedCellProofs := blobCount * numberOfColumns
   108→
   109→	if uint64(len(cellProofs)) != expectedCellProofs {
   110→		return errors.Errorf("expected %d cell proofs, got %d", expectedCellProofs, len(cellProofs))
   111→	}
   112→
   113→	if len(commitments) != len(blobs) {
   114→		return errors.Errorf("number of commitments (%d) must match number of blobs (%d)", len(commitments), len(blobs))
   115→	}
   116→
   117→	if blobCount == 0 {
   118→		return nil
   119→	}
   120→
   121→	// Handle multiple blobs - compute cells for all blobs
   122→	allCells := make([]Cell, 0, expectedCellProofs)
   123→	allCommitments := make([]Bytes48, 0, expectedCellProofs)
   124→	allIndices := make([]uint64, 0, expectedCellProofs)
   125→	allProofs := make([]Bytes48, 0, expectedCellProofs)
   126→
   127→	for blobIndex := range blobs {
   128→		if len(blobs[blobIndex]) != len(Blob{}) {
   129→			return fmt.Errorf("blobs len (%d) differs from expected (%d)", len(blobs[blobIndex]), len(Blob{}))
   130→		}
   131→		// Convert blob to kzg.Blob type
   132→		blob := Blob(blobs[blobIndex])
   133→
   134→		// Compute cells for this blob
   135→		cells, err := ComputeCells(&blob)
   136→		if err != nil {
   137→			return errors.Wrapf(err, "failed to compute cells for blob %d", blobIndex)
   138→		}
   139→
   140→		// Add cells and corresponding data for each column
   141→		for columnIndex := range numberOfColumns {
   142→			cellProofIndex := uint64(blobIndex)*numberOfColumns + columnIndex
   143→			if len(commitments[blobIndex]) != len(Bytes48{}) {
   144→				return fmt.Errorf("commitments len (%d) differs from expected (%d)", len(commitments[blobIndex]), len(Bytes48{}))
   145→			}
   146→			if len(cellProofs[cellProofIndex]) != len(Bytes48{}) {
   147→				return fmt.Errorf("proofs len (%d) differs from expected (%d)", len(cellProofs[cellProofIndex]), len(Bytes48{}))
   148→			}
   149→			allCells = append(allCells, cells[columnIndex])
   150→			allCommitments = append(allCommitments, Bytes48(commitments[blobIndex]))
   151→			allIndices = append(allIndices, columnIndex)
   152→
   153→			allProofs = append(allProofs, Bytes48(cellProofs[cellProofIndex]))
   154→		}
   155→	}
   156→
   157→	// Batch verify all cells
   158→	valid, err := VerifyCellKZGProofBatch(allCommitments, allIndices, allCells, allProofs)
   159→	if err != nil {
   160→		return errors.Wrap(err, "cell batch verification")
   161→	}
   162→	if !valid {
   163→		return errors.New("cell KZG proof batch verification failed")
   164→	}
   165→
   166→	return nil
   167→}
