    21→/**
    22→ * Serialize a 64-bit unsigned integer into bytes.
    23→ *
    24→ * @param[out]  out An 8-byte array to store the serialized integer
    25→ * @param[in]   n   The integer to be serialized
    26→ *
    27→ * @remark The output format is big-endian.
    28→ */
    29→void bytes_from_uint64(uint8_t out[8], uint64_t n) {
    30→    for (int i = 7; i >= 0; i--) {
    31→        out[i] = n & 0xFF;
    32→        n >>= 8;
    33→    }
    34→}
    35→
    36→/**
    37→ * Serialize a G1 group element into bytes.
    38→ *
    39→ * @param[out]  out A 48-byte array to store the serialized G1 element
    40→ * @param[in]   in  The G1 element to be serialized
    41→ */
    42→void bytes_from_g1(Bytes48 *out, const g1_t *in) {
    43→    blst_p1_compress(out->bytes, in);
    44→}
