    46→/**
    47→ * Serialize a BLS field element into bytes.
    48→ *
    49→ * @param[out]  out A 32-byte array to store the serialized field element
    50→ * @param[in]   in  The field element to be serialized
    51→ */
    52→void bytes_from_bls_field(Bytes32 *out, const fr_t *in) {
    53→    blst_scalar s;
    54→    blst_scalar_from_fr(&s, in);
    55→    blst_bendian_from_scalar(out->bytes, &s);
    56→}
